import{_ as o,o as t,c as a,an as n}from"./chunks/framework.9A8ojO3o.js";const p=JSON.parse('{"title":"변경 내역","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognal.cdget.com/ko/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://lognal.cdget.com/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://lognal.cdget.com/ko/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://lognal.cdget.com/changelog"}],["meta",{"property":"og:title","content":"변경 내역 | lognal"}],["meta",{"property":"og:description","content":"캔버스에 그리는 터미널 스타일의 브라우저 로그 뷰어입니다. 콘솔 출력을 옮겨 보여 주고, 로그 파일을 읽고, 값을 펼치고 접으며 살펴볼 수 있습니다."}],["meta",{"property":"og:url","content":"https://lognal.cdget.com/ko/changelog"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"name":"twitter:title","content":"변경 내역 | lognal"}],["meta",{"name":"twitter:description","content":"캔버스에 그리는 터미널 스타일의 브라우저 로그 뷰어입니다. 콘솔 출력을 옮겨 보여 주고, 로그 파일을 읽고, 값을 펼치고 접으며 살펴볼 수 있습니다."}]]},"headers":[],"relativePath":"ko/changelog.md","filePath":"ko/changelog.md","lastUpdated":null}'),s={name:"ko/changelog.md"};function d(i,e,l,r,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="변경-내역" tabindex="-1">변경 내역 <a class="header-anchor" href="#변경-내역" aria-label="Permalink to &quot;변경 내역&quot;">​</a></h1><p>변경 내역은 영어로 작성합니다. 두 패키지는 각자 버전을 올립니다.</p><div class="lognal-fw" data-fw="js"><p>npm 패키지입니다.</p><h2 id="vnext-2026" tabindex="-1">vNext (2026--) <a class="header-anchor" href="#vnext-2026" aria-label="Permalink to &quot;vNext (2026--)&quot;">​</a></h2><ul><li>A blank line in the stack trace of a logged error no longer becomes an empty row under it.</li></ul><h2 id="_1-0-0-2026-09-17" tabindex="-1">1.0.0 (2026-09-17) <a class="header-anchor" href="#_1-0-0-2026-09-17" aria-label="Permalink to &quot;1.0.0 (2026-09-17)&quot;">​</a></h2><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li><code>ViewerLabels</code> has twenty-two new labels: <code>entryActions</code>, <code>copyEntry</code>, <code>copyEntryWithTime</code>, <code>copyEntryFormatted</code>, <code>copyEntryData</code>, <code>expandAll</code>, <code>collapseAll</code>, <code>search</code>, <code>searchPrevious</code>, <code>searchNext</code>, <code>searchClose</code>, <code>searchCase</code>, <code>searchRegex</code>, <code>searchInvalid</code>, <code>searchResults</code>, <code>openLink</code>, <code>linkDialogTitle</code>, <code>linkDialogMessage</code>, <code>linkDialogOpen</code>, <code>linkDialogCancel</code>, <code>selectEntries</code> and <code>selectedEntries</code>. A complete <code>ViewerLabels</code> object of your own needs all of them. Overrides passed in <code>labels</code> are not affected.</li><li><code>RenderTheme</code> has the new colors <code>hover</code>, <code>searchMatch</code>, <code>searchCurrent</code>, <code>link</code>, <code>entrySelection</code> and <code>focusRing</code>, and <code>RowDecoration</code> the new fields <code>hovered</code>, <code>searchMatches</code>, <code>searchCurrent</code>, <code>entrySelected</code> and <code>entryFocused</code>. A <code>RenderTheme</code> object built by hand needs the six colors; spreading <code>DEFAULT_RENDER_THEME</code> covers them.</li><li><code>ToolbarOptions</code> has the new key <code>selectionMode</code>, and the toolbar shows its button by default. A complete <code>ToolbarOptions</code> object of your own needs the key.</li><li><code>LineAction</code> has a new type, <code>{ type: &#39;open-link&#39;; url: string }</code>, on the spans of links. Code that handles every type of action, such as a custom renderer, needs to handle it too.</li><li><code>theme: &#39;auto&#39;</code> is resolved to <code>light</code> or <code>dark</code> before it is written to the <code>data-theme</code> attribute, so <code>.lognal[data-theme=&#39;auto&#39;]</code> no longer matches anything. CSS that overrode a color inside a <code>prefers-color-scheme: dark</code> media query for <code>data-theme=&#39;auto&#39;</code> can drop that block and keep the one for <code>data-theme=&#39;dark&#39;</code>.</li><li><code>ToolbarOptions</code> has the new key <code>theme</code>, and the toolbar shows its button by default. A complete <code>ToolbarOptions</code> object of your own needs the key.</li><li><code>ViewerLabels</code> has the new labels <code>expandRepeats</code>, <code>collapseRepeats</code>, <code>mute</code>, <code>muteMessage</code>, <code>muteEmpty</code>, <code>muteText</code>, <code>muteAdd</code>, <code>muteRemove</code>, <code>muteEnabled</code>, <code>muteClose</code> and <code>muteCount</code>.</li><li><code>ToolbarOptions</code> has the new key <code>mute</code>, and the toolbar shows its button by default. A complete <code>ToolbarOptions</code> object of your own needs the key.</li><li><code>CompiledFilter</code> has the new field <code>muted</code>, which tests an entry against the mute rules. A <code>CompiledFilter</code> object built by hand needs it.</li><li><code>LineAction</code> has a new type, <code>{ type: &#39;toggle-repeat&#39; }</code>. Code that handles every type of action, such as a custom renderer, needs to handle it too.</li><li><code>ViewerLabels</code> has the new labels <code>theme</code>, <code>themeAuto</code>, <code>themeLight</code>, <code>themePaper</code>, <code>themeDark</code>, <code>themeMidnight</code>, <code>themeEmber</code> and <code>themeMoss</code>.</li><li>The level menu in the toolbar is a <code>&lt;button class=&quot;lognal-levels&quot;&gt;</code> that opens a list box, instead of a <code>&lt;select&gt;</code>. Styles or tests written for the <code>&lt;select&gt;</code> need to target the button and its menu.</li><li>The level menu chooses any set of levels and writes them to <code>levels</code> on the filter, where it wrote <code>minLevel</code> before. <code>levelLog</code>, <code>levelInfo</code>, <code>levelWarn</code> and <code>levelError</code> are now the names of the levels, such as <strong>Warning</strong> instead of <strong>Warnings and errors</strong>, and <code>ViewerLabels</code> has the new labels <code>levelDebug</code> and <code>levelSome</code>. Code that read <code>minLevel</code> after a user chose a level reads <code>levels</code> instead. <code>setFilter({ minLevel })</code> still works.</li></ul><h3 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h3><ul><li>The level menu follows the theme of the viewer. The arrow keys, Home and End move through the levels, Enter or Space chooses one, and Escape closes it.</li><li>The entry under the pointer gets a light background, set with <code>--lognal-hover</code>, and a button that opens a menu of actions for it. <strong>Copy as text</strong> copies the whole entry as plain text, with every captured value written out in full on one line, even when the value is closed, and <strong>Copy with timestamp</strong> puts the time of the entry in front. <strong>Copy as formatted text</strong> breaks long values over indented lines and adds HTML with the colors of the theme for rich text, and <strong>Copy as data</strong> copies the values as JSON. A long press opens the menu on a touch screen, and Shift+F10 or the context menu key opens it from the keyboard.</li><li><code>entryMenu</code> takes <code>false</code> to turn the menu off, or an object whose <code>items</code> function adds items of your own after the built-in ones. <code>getEntryText</code> and <code>copyEntry</code> do the same from code, with <code>format: &#39;text&#39; | &#39;formatted&#39; | &#39;data&#39;</code> and <code>timestamp: true</code>.</li><li><strong>Expand all</strong> and <strong>Collapse all</strong> in the entry menu open or close every value of an entry at once, and so do <code>expandEntry</code> and <code>collapseEntry</code>.</li><li>Ctrl+F or Cmd+F, while focus is in the viewer, opens a search bar over the log. Unlike the filter, it hides nothing: every match is highlighted, the current one more strongly, and Enter, F3 or Ctrl+G move between matches. Toggles, also on Alt+C and Alt+R, make the search match letter case or read the text as a regular expression. <code>openSearch</code>, with <code>caseSensitive</code> and <code>regex</code>, <code>closeSearch</code>, <code>findNext</code> and <code>findPrevious</code> do the same from code, <code>search: false</code> turns it off, and <code>--lognal-search-match</code> and <code>--lognal-search-current</code> color it.</li><li>The log area, the input line and the filter field no longer draw a focus outline.</li><li><code>--lognal-popup-shadow</code> sets the shadow of the level menu and the entry menu.</li><li>Enter at the end of Korean text in the input line submits the command with one press. Before, the first press added a line and the second one submitted. Enter that confirms a Japanese or Chinese candidate still does not submit.</li><li>A tap on a value or a group header on a touch screen opens or closes it, as a click does. Before, a tap did nothing.</li><li><code>http</code> and <code>https</code> addresses in the log are drawn as links in <code>--lognal-link</code> and open in a new tab. <code>linkClick</code> decides what a click or a tap does: <code>&#39;confirm&#39;</code>, the default, shows the address in a dialog and asks first, <code>&#39;open&#39;</code> opens the link right away, and <code>&#39;ignore&#39;</code> only draws it. <code>core: { links: false }</code> draws addresses as plain text. The entry menu lists the links of an entry, so they also open from the keyboard, and <code>findLinks</code> finds the addresses in a string.</li><li>A click with Shift, Ctrl, Alt or Cmd held on a value, a group header or a link selects text instead of opening it. The exception is Ctrl+click, or Cmd+click on macOS, on a link in text mode: it opens the link right away, without the dialog, unless <code>linkClick</code> is <code>&#39;ignore&#39;</code>.</li><li><code>selectionMode: &#39;entry&#39;</code> selects whole entries the way a file manager selects files. A click selects an entry, Ctrl or Cmd adds or removes one, Shift selects a range, and a drag selects the entries it passes over. The arrow keys, Home, End, Page Up and Page Down move from entry to entry and outline the entry in <code>--lognal-focus-ring</code>, Space selects the entry the keyboard is on, and Ctrl+A, Ctrl+C and Escape select every entry, copy the selection and clear it. A right click, Shift+F10 or the context menu key opens a menu that copies the selected entries in the formats of the entry menu, or opens and closes their values. The <strong>Select whole entries</strong> button in the toolbar switches modes, <code>--lognal-entry-selection</code> colors the selected entries, and the status bar counts them.</li><li><code>getSelectionText</code> and <code>copySelection</code> take the options of <code>getEntryText</code> in entry mode, and <code>getSelectedEntryIds</code> returns the ids of the selected entries.</li><li>In entry mode, a drag that starts on the empty space around the entries selects the entries it reaches, starting from the entry nearest the press. Before, such a drag selected nothing.</li><li><code>LogFilter</code> takes <code>mute</code>, a list of <code>MuteRule</code> objects that keep matching entries out of the log whatever the rest of the filter says. A rule is plain text or a regular expression, matches letter case only when it is asked to, and <code>enabled: false</code> keeps it without applying it. The <strong>Hidden messages</strong> button in the toolbar opens a dialog that manages the rules and carries the number of entries they hide; <code>getMuteRules</code>, <code>setMuteRules</code>, <code>getMutedCount</code> and <code>openMuteDialog</code> do the same from code, <code>layout.mutedCount</code> counts them, and <code>toolbar: { mute: false }</code> hides the button. The rules sit in a box of a fixed height that scrolls, so adding or removing one leaves the dialog where it is, and every control of the dialog that has no visible name shows one while the pointer rests on it.</li><li><code>core: { mergeRepeats: &#39;collapse&#39; }</code> keeps every message of a run of identical messages instead of dropping them. The run shows as its first entry with the count, and the count badge opens it to show each message; <strong>Show repeats</strong> and <strong>Hide repeats</strong> in the entry menu do the same. <code>a a b a a</code> reads as <code>a</code> twice, <code>b</code>, then <code>a</code> twice. <code>mergeRepeats</code> still takes <code>true</code>, the default, and <code>false</code>.</li><li><code>LogEntry</code> has the new field <code>runHead</code>, the id of the entry a repeated message belongs to, <code>store.isRunHead</code> tells whether an entry starts a run, and a <code>&#39;update&#39;</code> store change carries <code>visibility: true</code> when it hides or shows other entries.</li><li>Four palettes join <code>light</code> and <code>dark</code>: <code>paper</code>, a warm light one, and the dark <code>midnight</code>, <code>ember</code> and <code>moss</code>. <code>BUILT_IN_THEMES</code> lists them, and <code>theme</code> also takes a name of your own, which the viewer writes to <code>data-theme</code> so one block of CSS is a whole theme.</li><li>The <strong>Theme</strong> button in the toolbar opens a menu of the themes. <code>themes</code> chooses which ones it offers, as names or as <code>{ name, label }</code> objects, and <code>toolbar: { theme: false }</code> hides the button.</li><li>Every palette is written once in <code>lognal.css</code>, rather than a second time inside a media query for <code>auto</code>. <code>--lognal-on-accent</code> sets the text color on the accent background of the <strong>New logs</strong> button and the primary dialog button.</li><li>The level menu lists every level, <code>debug</code> included, with a mark next to the ones the log shows, and it stays open while levels are chosen. While every level is shown, choosing one shows that level alone; after that, choosing a level adds it or takes it away, and <strong>All levels</strong> shows them all again. The button names the only level shown, the number of levels, or <strong>All levels</strong>.</li><li>A toolbar control shows its name in a small label as soon as the pointer reaches it, instead of waiting for the tooltip of the browser. The label also appears when the keyboard moves to the control, and <code>tooltips: false</code> leaves the tooltip to the browser.</li></ul><h2 id="_0-1-0-2026-09-13" tabindex="-1">0.1.0 (2026-09-13) <a class="header-anchor" href="#_0-1-0-2026-09-13" aria-label="Permalink to &quot;0.1.0 (2026-09-13)&quot;">​</a></h2><p>The first release.</p><ul><li><code>LogViewer</code> shows logs drawn on a canvas, with a toolbar (follow new logs, clear, scroll to top and bottom, line wrapping, text filter, level filter), a status bar, timestamps and an optional input line for commands.</li><li><code>hookConsole</code> and <code>createConsole</code> record console calls. Arguments are captured when the method is called, and format specifiers, counters, timers, groups and <code>console.table</code> follow the Console Standard.</li><li>Logged objects, arrays, maps, sets, errors and DOM elements expand and collapse. Getters are never run while a value is captured.</li><li>Text written with <code>wrap: false</code>, and the output of <code>console.table</code>, keeps its lines on one row. When such a line is wider than the viewer, the log scrolls sideways.</li><li>A large log lays out the rows on screen first and the rest in small steps between frames, so changing the width does not stall the page. While the view is not following, the entry at its top stays in place when rows above it change height.</li><li><code>readTextFile</code> reads a text file in chunks and detects UTF-8, UTF-16 and the legacy encoding of the browser language, such as EUC-KR. <code>followTextFile</code> keeps reading a growing file in Chromium-based browsers.</li><li>Korean, Chinese, Japanese and emoji take two cells, Korean text wraps at spaces, and Enter in the input line waits for IME composition to finish.</li><li>Light, dark and automatic themes come from <code>--lognal-*</code> CSS custom properties in <code>lognal/style.css</code>.</li><li><code>lognal/react</code> provides a <code>LogViewer</code> React component.</li></ul></div><div class="lognal-fw" data-fw="flutter"><p>pub.dev 패키지입니다.</p><h2 id="vnext-2026-1" tabindex="-1">vNext (2026--) <a class="header-anchor" href="#vnext-2026-1" aria-label="Permalink to &quot;vNext (2026--)&quot;">​</a></h2><h3 id="breaking-changes-1" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-1" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li><code>ChromeTheme</code> has the new color <code>error</code>, which marks a field whose text is not a pattern that compiles. A <code>ChromeTheme</code> built by hand needs it; <code>buildTheme</code> and the six palettes it ships already have it. Before this a field marked itself in the accent color, which is what a field in focus is drawn in, so nothing told the two apart.</li></ul><h3 id="changes-1" tabindex="-1">Changes <a class="header-anchor" href="#changes-1" aria-label="Permalink to &quot;Changes&quot;">​</a></h3><ul><li>The log is cut off at the edges of the area it is drawn in, so the row that a scroll leaves half above the top no longer paints over the toolbar.</li><li>The text of a row is centred in it, so it lines up with the level marks, the expanders and the box-drawing lines beside it instead of sitting above them. The underline of a link and the line through struck-out text move with it.</li><li>A blank line in the stack trace of a logged error no longer becomes an empty row under it.</li><li>The toolbar menus, the entry menu and the link and hidden-message dialogs open again. The viewer draws them over itself instead of pushing a route onto the application&#39;s navigator, so they work in an application that has none, such as a <code>WidgetsApp</code> with nothing but a <code>builder</code>.</li><li>The pointer over the log says what a press would do, the way the stylesheet already says it on the web: a bar over text to select, a hand over a link or an expander, and an arrow while whole entries are being picked out.</li><li>The sentence a dialog explains itself with wraps instead of ending in an ellipsis.</li><li>A right press opens the menu of the selected entries in entry mode, and is left to the platform in the mode where the log is read, which is what the npm package has always done. The entry under the press is selected alone first when it was not already selected.</li><li>On the web, the browser no longer draws its own menu over the entry menu. The viewer turns the browser&#39;s menu off while it is in entry mode and puts it back as soon as no viewer is.</li><li>A menu that would have no items in it does not open.</li><li>A rule in the <strong>Hidden messages</strong> dialog is edited where it stands: its text in a field of its own, and <strong>Match case</strong> and <strong>Use regular expression</strong> beside it, as in the npm package. A rule whose regular expression does not compile marks its field, once the keyboard has left it: while it is being written, the border says where the keyboard is instead.</li><li>The toolbar puts the filter and the levels on a second line when the viewer is too narrow to hold them beside the buttons, instead of running off the right edge. The filter gives way to 96 pixels before that happens, as it does on the web.</li><li>Two buttons of the toolbar or the search bar no longer touch, so a pair of toggles that are both on reads as two buttons rather than one. The space around the lines between groups is unchanged.</li><li>The level menu stays open while levels are added and taken away, so a set of them is a few presses rather than a few trips to the button. A press outside it closes it.</li><li>A filter, a mute rule or anything else that leaves fewer rows behind no longer scrolls the log off the bottom of the view. The view comes back inside the log it is showing, and a view that was following new entries stays at the end.</li></ul><h2 id="_1-0-0-2026-09-17-1" tabindex="-1">1.0.0 (2026-09-17) <a class="header-anchor" href="#_1-0-0-2026-09-17-1" aria-label="Permalink to &quot;1.0.0 (2026-09-17)&quot;">​</a></h2><p>The first release, and the same library the npm package has shipped since <code>0.1.0</code>, translated file for file.</p><ul><li><code>LogViewer</code> shows logs drawn on a canvas, with a toolbar (follow new logs, clear, scroll to top and bottom, line wrapping, entry selection, themes, hidden messages, text filter and level filter), a status bar, timestamps, its own scrollbars and an optional input line for commands. <code>LogViewerController</code> holds the state, so log entries never go through <code>setState</code>.</li><li><code>hookDebugPrint</code>, <code>runZonedWithLognal</code> and <code>hookFlutterErrors</code> record what the application already prints: the first replaces the variable Flutter prints through and puts it back, the second catches <code>print</code>, which belongs to the zone rather than to a variable, and the third puts a failed build in the log with its stack.</li><li><code>LognalConsole</code> writes into a store from your own code, with the levels, groups, counters, timers, assertions and tables a console has, and the format specifiers <code>%s</code>, <code>%d</code>, <code>%i</code>, <code>%f</code>, <code>%o</code>, <code>%O</code> and <code>%c</code>.</li><li><code>captureValue</code> takes a value as it was at the moment of the call. A class that writes <code>toJson()</code> opens into its properties, one that writes <code>toString()</code> shows what it says, and the rest show their type. Depth, item count, string length and total node count each have a limit, and whatever they cut is counted.</li><li>Logged lists, maps, sets and errors expand and collapse, an error is open by default so its stack is visible, and <code>console.table</code> draws a table whose columns line up around wide characters.</li><li><code>readTextStream</code> and <code>readTextBytes</code> read a text file one entry per line, from a file on disk or the bytes a browser handed the page. <code>followTextFile</code> keeps reading a file as it grows, and reads it again from the start when it was replaced. UTF-8, UTF-16, Latin-1 and Windows-1252 decode here, and <code>registerTextDecoder</code> takes a legacy CJK decoder from your application.</li><li>Korean, Chinese, Japanese and emoji take two cells, Korean text wraps at spaces, the filter and the search compare text in Unicode normalization form C so decomposed Hangul matches what a reader types, and the input line is a real text field, so an input method composes into it.</li><li>Text written with <code>wrap: false</code>, and the output of a table, keeps its lines on one row; a line wider than the viewer scrolls sideways.</li><li>A large log lays out the rows on screen first and the rest in small steps between frames. While the view is not following, the entry at its top stays in place when rows above it change height.</li><li><code>core: mergeRepeats</code> merges identical consecutive messages into a repeat count, or keeps them as a run that opens from the count badge.</li><li><code>LogFilter</code> takes <code>mute</code>, rules that keep matching entries out of the log whatever the rest of the filter says, with a dialog in the toolbar that manages them.</li><li>The search bar highlights every match without hiding an entry, and matches letter case or reads the text as a regular expression when asked.</li><li><code>selectionMode</code> selects whole entries the way a file manager selects files, with the arrow keys, Shift and the platform&#39;s own multi-select modifier.</li><li><code>http</code> and <code>https</code> addresses in the text are drawn as links; <code>linkClick</code> decides whether a tap asks first, opens straight away, or does nothing, and <code>onOpenLink</code> is what actually opens one.</li><li>Six palettes — <code>light</code>, <code>paper</code>, <code>dark</code>, <code>midnight</code>, <code>ember</code> and <code>moss</code> — with <code>auto</code> following the system. <code>buildTheme</code> makes one of your own out of a background, an accent and a sixteen-colour ramp.</li><li>English and Korean labels, with <code>labels</code> to replace any of them.</li></ul></div>',4)])])}const u=o(s,[["render",d]]);export{p as __pageData,u as default};
